sub _token_needs_trailing_space {
    my ($tok) = @_;

    my %need_space = map { $_ => 1 } qw(
        RUN NEW CONT PASS LIST LLIST CLOAD MERGE LOAD RENUM AUTO DELETE FILES INIT CONVERT
        CSAVE OPEN CLOSE SAVE CONSOLE RANDOM DEGREE RADIAN GRAD BEEP WAIT GOTO TRON TROFF CLEAR USING
        DIM CALL POKE GPRINT BASIC TEXT ERASE LFILES KILL COPY NAME SET
        LTEXT GRAPH LF CSIZE COLOR DEFDBL DEFSNG
        CLS PSET LINE CURSOR GCURSOR TO STEP THEN ON IF FOR LET REM END NEXT STOP READ DATA PAUSE
        PRINT INPUT GOSUB AREAD LPRINT RETURN RESTORE CHAIN
        PAINT OUTPUT APPEND AS ARUN AUTOGOTO ERROR
    );

    return $need_space{$tok} ? 1 : 0;
}

sub find_and_extract_basic {
    my ($raw_ref) = @_;
    my @b = ref($raw_ref) eq 'ARRAY' ? @$raw_ref : unpack('C*', $raw_ref);

    my $n = scalar @b;
    for (my $i = 0; $i < $n - 10; $i++) {
        my $type_pos;

        if ($b[$i] == 0x27 || $b[$i] == 0x37) {
            $type_pos = $i;
        }
        elsif ($i + 1 < $n && $b[$i] == 0xFF && ($b[$i + 1] == 0x27 || $b[$i + 1] == 0x37)) {
            $type_pos = $i + 1;
        }
        else {
            next;
        }

        next unless $type_pos + 9 < $n;
        next unless $b[$type_pos + 8] == 0xF5;

        my @name_rev = @b[$type_pos + 1 .. $type_pos + 7];
        my $name = _decode_reversed_name_7(@name_rev);

        my $pos = $type_pos + 10;  # type + 7 name + F5 + checksum
        my @body_raw;

        while ($pos < $n) {
            last if $pos + 2 < $n && $b[$pos] == 0xFF && $b[$pos + 1] == 0xFF;

            my $remain = $n - $pos;

            if ($remain >= 123) {
                my @chunk = @b[$pos .. $pos + 119];

                if ($b[$pos + 120] == 0xFF && $b[$pos + 121] == 0xFF) {
                    push @body_raw, @chunk;
                    $pos += 120;
                    next;
                }

                push @body_raw, @chunk;
                $pos += 121;  # 120 data + 1 checksum
                next;
            }

            while ($pos < $n) {
                last if $pos + 2 < $n && $b[$pos] == 0xFF && $b[$pos + 1] == 0xFF;
                push @body_raw, $b[$pos++];
            }
            last;
        }

        next unless $pos + 2 < $n;
        next unless $b[$pos] == 0xFF && $b[$pos + 1] == 0xFF;

        my @body = map { _nibble_swap($_) } @body_raw;

        return {
            offset     => $i,
            type_pos   => $type_pos,
            type       => $b[$type_pos],
            name       => $name,
            body_bytes => \@body,
        };
    }

    die "s2 basic header not found\n";
}

sub decode_s2_basic_body {
    my ($bytes) = @_;
    my @b = ref($bytes) eq 'ARRAY' ? @$bytes : unpack('C*', $bytes);
    my $pos = 0;

    $pos++ if @b && $b[0] == 0xFF;

    my @lines;

    while ($pos < @b) {
        last if $b[$pos] == 0xFF;

        die "truncated before line number\n" if $pos + 2 >= @b;

        my $line_no = ($b[$pos] << 8) | $b[$pos + 1];
        $pos += 2;

        my $line_len = $b[$pos++];
        die "invalid line length at line $line_no\n" if $line_len == 0;
        die "truncated line body at line $line_no\n" if $pos + $line_len - 1 >= @b;

        my @line = @b[$pos .. $pos + $line_len - 1];
        $pos += $line_len;

        my $eol = pop @line;
        die sprintf("line %d missing 0D (got %02X)\n", $line_no, $eol)
            unless $eol == 0x0D;

        my $stmt = _decode_line_tokens(\@line);
        push @lines, sprintf("%d:%s", $line_no, $stmt);
    }

    return join("", map { "$_\n" } @lines);
}

sub decode_s2_basic {
    my ($bytes) = @_;
    return decode_s2_basic_body($bytes);
}

sub _decode_line_tokens {
    my ($bytes_ref) = @_;
    my @bytes = @$bytes_ref;

    my @items;
    my @text_buf;

    my $flush_text = sub {
        return unless @text_buf;
        push @items, {
            type  => 'text',
            value => decode_text_for_s2(\@text_buf),
        };
        @text_buf = ();
    };

    my $in_quote  = 0;
    my $after_rem = 0;
    my $i = 0;

    while ($i < @bytes) {
        my $c = $bytes[$i];

        if ($after_rem) {
            push @text_buf, $c;
            $i++;
            next;
        }

        if ($in_quote) {
            push @text_buf, $c;
            $in_quote = 0 if $c == 0x22;
            $i++;
            next;
        }

        if ($c == 0x22) {
            push @text_buf, $c;
            $in_quote = 1;
            $i++;
            next;
        }

        # FE xx token
        if ($c == 0xFE) {
            if ($i + 1 >= @bytes) {
                push @text_buf, $c;
                last;
            }

            my $t = $bytes[$i + 1];
            my $tok = exists $TOKEN_MAP{$t} ? $TOKEN_MAP{$t} : undef;

            if (!defined $tok || $tok eq "\0") {
                push @text_buf, $c, $t;
                $i += 2;
                next;
            }

            $flush_text->();

            push @items, { type => 'token', value => $tok };
            $after_rem = 1 if $tok eq 'REM';

            $i += 2;
            next;
        }

        # line reference: 1F hh ll
        if ($c == 0x1F) {
            if ($i + 2 >= @bytes) {
                push @text_buf, $c;
                last;
            }

            $flush_text->();

            my $ref_line = ($bytes[$i + 1] << 8) | $bytes[$i + 2];
            push @items, { type => 'text', value => $ref_line };

            $i += 3;
            next;
        }

        if ($c >= 0x20 && $c <= 0x7E) {
            push @text_buf, $c;
            $i++;
            next;
        }

        # 半角カナ・漢字SJIS 2byte・未知byte は TextCodec 側で判定する
        push @text_buf, $c;
        $i++;
    }

    $flush_text->();

    return _format_items(@items);
}

sub _format_items {
    my @items = @_;
    my $out = '';

    for (my $i = 0; $i < @items; $i++) {
        my $cur  = $items[$i];
        my $prev = $i > 0       ? $items[$i - 1] : undef;
        my $next = $i < $#items ? $items[$i + 1] : undef;

        if ($cur->{type} eq 'text') {
            $out .= $cur->{value};
            next;
        }

        my $tok = $cur->{value};
        if ($tok eq 'REM') {
            if (_need_space_before_token($prev, $tok)) {
                $out .= ' ' unless $out =~ / $/;
            }
            $out .= 'REM ';
            next;
        }

        if (_need_space_before_token($prev, $tok)) {
            $out .= ' ' unless $out =~ / $/;
        }

        $out .= $tok;

        if (_need_space_after_token($tok, $next)) {
            $out .= ' ' unless $out =~ / $/;
        }
    }

    # コロンや行末の余計な空白を整理
    $out =~ s/[ ]+:/:/g;
    $out =~ s/:[ ]+/:/g;
    $out =~ s/[ ]+$//;

    # 二重空白を1個に圧縮（文字列/REM中は items化の時点で保持済みなのでここは実質安全）
    #$out =~ s/ {2,}/ /g;

    # ただし "( " は "(" に、"; " は ";" に寄せる
    $out =~ s/\( +/(/g;
    $out =~ s/; +/;/g;

    return $out;
}

sub _need_space_before_token {
    my ($prev, $tok) = @_;
    return 0 unless $prev;

    return 1 if $SPACE_AROUND_TOKENS{$tok};

    return 0 unless $prev->{type} eq 'text';
    my $pv = $prev->{value};
    return 0 unless length $pv;

    my $ch = substr($pv, -1, 1);

    # 英数字・$・"・) の直後なら区切る
    return 1 if $ch =~ /[A-Za-z0-9\$\")]|\)/;

    return 0;
}

sub _need_space_after_token {
    my ($tok, $next) = @_;
    return 0 unless $next;

    # まず、空白候補トークンでなければ入れない
    return 0 unless $SPACE_AROUND_TOKENS{$tok} || $SPACE_AFTER_TOKENS{$tok};

    # 次が text の場合、中身を見る
    if ($next->{type} eq 'text') {
        my $nv = $next->{value};

        # すでに空白なら追加しない
        return 0 if $nv =~ /^ /;

        # 次が "(" なら空白を入れない
        return 0 if $nv =~ /^\(/;
    }

    return 1;
}

sub _decode_reversed_name_7 {
    my (@blk) = @_;
    my @chars = reverse @blk;
    my $name = join '', map { ($_ >= 0x20 && $_ <= 0x7E) ? chr($_) : '' } grep { $_ != 0x00 } @chars;
    $name =~ s/\s+$//;
    return $name;
}

#sub _decode_text_char {
#    my ($c) = @_;
#    return chr($c) if $c >= 0x20 && $c <= 0x7E;
#    return '?';
#}

sub _nibble_swap {
    my ($v) = @_;
    return (($v & 0x0F) << 4) | (($v & 0xF0) >> 4);
}

1;
}

# ----- END bundled module: PCWAV::Basic::S2Decode -----

# ----- BEGIN bundled module: PCWAV::Format::Old -----
{
BEGIN { $INC{'PCWAV/Format/Old.pm'} = __FILE__; }
package PCWAV::Format::Old;
use strict;
use warnings;
PCWAV::Common->import(());

our $CHUNK_SIZE = 8;

sub chunk_size {
    return $CHUNK_SIZE;
}

# -----------------------------
# Encode
# -----------------------------

sub wrap_basic_payload {
    my (%opt) = @_;

    my $type     = $opt{password} ? 0x12 : 0x02;   # rawで見える値
    my @filename = @{ _normalize_filename($opt{filename} // '') };  # rawで見える順
    my @body     = _to_bytes($opt{body});

    my @out;

    # type は単独
    push @out, $type;

    # filename(7)+F5 が最初の 8byte ブロック
    my @name_block = (@filename, 0xF5);
    push @out, @name_block;
    push @out, PCWAV::Common::nibswap(
        PCWAV::Common::checksum_old_logical(@name_block)
    );

    # body は論理値 -> raw側表現(nibswap) にしてから 8byte checksum
    my @body_raw = map { PCWAV::Common::nibswap($_) } @body;
    push @out, _insert_old_checksums_cumulative(@body_raw);

    return wantarray ? @out : pack('C*', @out);
}

sub wrap_binary_payload {
    my (%opt) = @_;

    my $start_addr = $opt{start_addr};
    my $end_offset = $opt{end_offset};

    die "wrap_binary_payload: start_addr is required\n"
        unless defined $start_addr;
    die "wrap_binary_payload: end_offset is required\n"
        unless defined $end_offset;

    my $type     = 0x62;  # rawで見える値
    my @filename = @{ _normalize_filename($opt{filename} // '') };
    my @body     = _to_bytes($opt{body});

    my @meta_raw = (
        0x00, 0x00, 0x00, 0x60,
        ($start_addr >> 8) & 0xFF,
        $start_addr & 0xFF,
        ($end_offset >> 8) & 0xFF,
        $end_offset & 0xFF,
    );

    my @out;

    push @out, $type;

    my @name_block = (@filename, 0xF5);
    push @out, @name_block;
    push @out, PCWAV::Common::nibswap(
        PCWAV::Common::checksum_old_logical(@name_block)
    );

    # binary meta も raw のまま 8byte + checksum
    push @out, @meta_raw;
    push @out, PCWAV::Common::nibswap(
        PCWAV::Common::checksum_old_logical(@meta_raw)
    );

    # body は raw側表現にしてから chunk checksum
    my @body_raw = map { PCWAV::Common::nibswap($_) } @body;
    push @out, _insert_old_checksums_cumulative(@body_raw);

    return wantarray ? @out : pack('C*', @out);
}

# -----------------------------
# Decode
# -----------------------------

sub unwrap_payload {
    my ($raw) = @_;
    my @raw = _to_bytes($raw);

    die "unwrap_payload: too short\n" unless @raw >= 10;

    # type は単独
    my $type = shift @raw;

    # filename(7)+F5
    my @name_block = splice(@raw, 0, 8);
    my $name_sum   = shift @raw;

    die "unwrap_payload: truncated OLD filename block\n"
        unless @name_block == 8 && defined $name_sum;

    my @filename = @name_block[0 .. 6];
    my $f5       = $name_block[7];

    die sprintf("unwrap_payload: invalid OLD filename terminator %02X\n", $f5)
        unless $f5 == 0xF5;

    # 実機 raw では filename block 自体はそのまま見え、
    # checksum byte は nibswap された見え方になる
    my $want_name_sum = PCWAV::Common::checksum_old_logical(@name_block);
    my $got_name_sum  = PCWAV::Common::nibswap($name_sum);

    die sprintf("OLD filename checksum mismatch: got=%02X want=%02X\n", $got_name_sum, $want_name_sum)
        if $got_name_sum != $want_name_sum;

    if ($type == 0x02 || $type == 0x12) {
        my @body_logical = _remove_old_checksums_body_stream(@raw);

        return {
            kind       => 'basic',
            password   => ($type == 0x12 ? 1 : 0),
            type       => $type,
            filename   => _decode_filename_raw(@filename),
            body_bytes => \@body_logical,
        };
    }
    elsif ($type == 0x62) {
        die "unwrap_payload: truncated OLD binary metadata\n" unless @raw >= 9;

        my @meta_raw = splice(@raw, 0, 8);
        my $meta_sum = shift @raw;

        my $want_meta_sum = PCWAV::Common::checksum_old_logical(@meta_raw);
        my $got_meta_sum  = PCWAV::Common::nibswap($meta_sum);

        die sprintf("OLD binary meta checksum mismatch: got=%02X want=%02X\n", $got_meta_sum, $want_meta_sum)
            if $got_meta_sum != $want_meta_sum;

        my @reserved = @meta_raw[0 .. 3];
        my $start_addr = ($meta_raw[4] << 8) | $meta_raw[5];
        my $end_offset = ($meta_raw[6] << 8) | $meta_raw[7];

        my @body_logical = _remove_old_checksums_body_stream(@raw);

        return {
            kind       => 'binary',
            type       => $type,
            filename   => _decode_filename_raw(@filename),
            reserved   => \@reserved,
            start_addr => $start_addr,
            end_offset => $end_offset,
            body_bytes => \@body_logical,
        };
    }
    else {
        die sprintf("unwrap_payload: unknown OLD raw type %02X\n", $type);
    }
}

# -----------------------------
# Internal helpers
# -----------------------------

sub _insert_old_checksums {
    my (@bytes) = @_;
    my @out;

    while (@bytes >= $CHUNK_SIZE) {
        my @chunk = splice(@bytes, 0, $CHUNK_SIZE);
        my $sum   = PCWAV::Common::checksum_old_logical(@chunk);
        push @out, @chunk, $sum;
    }

    push @out, @bytes;   # 端数には checksum なし
    return @out;
}

sub _insert_old_checksums_cumulative {
    my (@bytes) = @_;
    my @out;

    my $sum = 0;
    my $chunk_no = 0;

    while (@bytes >= $CHUNK_SIZE) {
        # OLD BASIC body checksum resets every 80 bytes
        # = every 10 chunks of 8 bytes.
        if ($chunk_no % 10 == 0) {
            $sum = 0;
        }

        my @chunk = splice(@bytes, 0, $CHUNK_SIZE);

        for my $b (@chunk) {
            # @bytes are already raw-side bytes, i.e. nibble-swapped.
            # Therefore logical high nibble corresponds to raw low nibble.
            $sum += ($b & 0x0F);
            $sum = ($sum + 1) & 0xFF if $sum > 0xFF;

            $sum = ($sum + (($b & 0xF0) >> 4)) & 0xFF;
        }

        push @out, @chunk, PCWAV::Common::nibswap($sum);
        $chunk_no++;
    }

    # Last partial block has no checksum.
    push @out, @bytes;

    return @out;
}

sub _remove_old_checksums_body {
    my (@raw_body) = @_;
    my @out;

    while (@raw_body >= $CHUNK_SIZE + 1) {
        my @chunk_raw = splice(@raw_body, 0, $CHUNK_SIZE);
        my $sum_raw   = shift @raw_body;

        # body chunk は rawでは nibswap 後に見えている。
        # checksum は logical値に対して計算され、保存時に nibswap された値になる。
        my @chunk_logical = map { PCWAV::Common::nibswap($_) } @chunk_raw;
        my $got           = PCWAV::Common::nibswap($sum_raw);
        my $want          = PCWAV::Common::checksum_old_logical(@chunk_logical);

        die sprintf("OLD checksum mismatch: got=%02X want=%02X\n", $got, $want)
            if $got != $want;

        push @out, @chunk_logical;
    }

    # 最後の余りは checksum なし。logical に戻して返す
    push @out, map { PCWAV::Common::nibswap($_) } @raw_body;

    return @out;
}

sub _remove_old_checksums_body_stream {
    my (@raw_body) = @_;

    my @out;
    my $sum = 0;
    my $chunk_no = 0;

    while (@raw_body >= $CHUNK_SIZE + 1) {
        if ($chunk_no % 10 == 0) {
            $sum = 0;
        }

        my @chunk_raw = splice(@raw_body, 0, $CHUNK_SIZE);
        my $sum_raw   = shift @raw_body;

        for my $b (@chunk_raw) {
            # raw-side nibble-swapped byte:
            # logical high nibble is raw low nibble.
            $sum += ($b & 0x0F);
            $sum = ($sum + 1) & 0xFF if $sum > 0xFF;

            $sum = ($sum + (($b & 0xF0) >> 4)) & 0xFF;
        }

        my $got = PCWAV::Common::nibswap($sum_raw);

        die sprintf("OLD checksum mismatch: got=%02X want=%02X\n", $got, $sum)
            if $got != $sum;

        push @out, map { PCWAV::Common::nibswap($_) } @chunk_raw;
        $chunk_no++;
    }

    # Last partial block has no checksum.
    push @out, map { PCWAV::Common::nibswap($_) } @raw_body;

    return @out;
}

sub _normalize_filename {
    my ($name) = @_;
    $name = uc($name // '');
    $name =~ s/\.[^.]+$//;
    $name =~ s/[^A-Z0-9]//g;
    $name = substr($name, 0, 7);

    # 実機 raw では逆順に見える
    my @chars = reverse split //, $name;
    my @bytes = map { _filename_char_to_code($_) } @chars;

    # 空きは 0x00 埋め
    while (@bytes < 7) {
        unshift @bytes, 0x00;
    }

    return \@bytes;
}

sub _decode_filename_raw {
    my (@bytes) = @_;

    my @chars;
    for my $b (@bytes) {
        next if $b == 0x00;
        push @chars, _filename_code_to_char($b);
    }

    return join('', reverse @chars);
}

sub _filename_char_to_code {
    my ($ch) = @_;

    if ($ch ge '0' && $ch le '9') {
        return 0x40 + ord($ch) - ord('0');
    }
    elsif ($ch ge 'A' && $ch le 'Z') {
        return 0x51 + ord($ch) - ord('A');
    }
    else {
        die "invalid OLD filename char: $ch\n";
    }
}

sub _filename_code_to_char {
    my ($b) = @_;

    return chr(ord('0') + ($b - 0x40)) if $b >= 0x40 && $b <= 0x49;
    return chr(ord('A') + ($b - 0x51)) if $b >= 0x51 && $b <= 0x6A;

    return '?';
}

sub _to_bytes {
    my ($v) = @_;
    return () unless defined $v;
    return @$v if ref($v) eq 'ARRAY';
    return unpack('C*', $v);
}

1;
}

